type SettingsMetadata struct {
	// Name of the setting.
	Name *string
	// Setting description for what this setting controls
	Description *string
	// Sample message depicting the type of the setting. To set this setting, the
	// value sent must match this type.
	Type *string
	// Link to databricks documentation for the setting
	DocsLink *string
	// Preview phase for feature preview settings. This field is not set for
	// non-preview settings.
	PreviewPhase PreviewPhase
	// Human-readable display name for the setting or feature preview. This field
	// may be unset if no display name is available.
	DisplayName *string
}

type StringMessage struct {
	// Represents a generic string value.
	Value *string
}

// User Preference represents a user-specific setting scoped to an individual
// user within an account. Unlike workspace or account settings that apply to
// all users, user preferences allow personal customization (e.g., UI theme,
// editor preferences) without affecting other users..
type UserPreference struct {
	// Name of the setting.
	Name *string
	// User ID of the user.
	UserId *string
	// New fields should be added before the oneof below - unless it's a new Setting
	// value message, in that case it needs to be defined in the oneof below. The
	// user-set value that goes into storage.
	Value isUserPreference_Value
	// New fields should be added before the oneof below - unless it's a new User
	// Preference value message, in that case it needs to be defined in the oneof
	// below. The final effective value from server as per the policy evaluation.
	EffectiveValue isUserPreference_EffectiveValue
}

